#!/usr/bin/env bash
# facts-rebuild.sh — validate facts.jsonl and emit row counts.
#
# Sprint 46.6.1 — Agent OS Memory v2: Temporal Facts Layer.
# JSONL is the source of truth. The spec's optional sqlite derived cache is
# not generated by default at this corpus size (~60 facts) — a native dep
# (better-sqlite3) adds install friction without a perf benefit. The script
# is named "rebuild" for forward-compat: a future sprint can derive a
# sqlite cache here without changing callers.
#
# Usage:  bash agent-os/scripts/facts-rebuild.sh
# Exits 0 when facts.jsonl parses and is non-empty; non-zero on parse error.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
REPO_ROOT="$(cd "$REPO_ROOT/.." && pwd)"
cd "$REPO_ROOT"

JSONL=agent-os/facts.jsonl

if [ ! -f "$JSONL" ]; then
  echo "facts-rebuild: $JSONL missing — run agent-os/scripts/facts-seed-from-rules.sh first" >&2
  exit 2
fi

# Parse-validate every line (jq if available, else node fallback).
if command -v jq >/dev/null 2>&1; then
  if ! jq -c . "$JSONL" >/dev/null; then
    echo "facts-rebuild: $JSONL failed jq parse" >&2
    exit 3
  fi
else
  if ! node -e '
    const fs = require("node:fs");
    const lines = fs.readFileSync("agent-os/facts.jsonl", "utf8").split("\n").filter(Boolean);
    for (const ln of lines) JSON.parse(ln);
  '; then
    echo "facts-rebuild: $JSONL failed node JSON.parse" >&2
    exit 3
  fi
fi

# Counts: distinct entities (subjects + objects), total triples.
node --input-type=module -e '
import { readAllFacts } from "./agent-os/scripts/facts-lib.mjs";
const all = readAllFacts();
const entities = new Set();
for (const f of all) {
  if (f.subject) entities.add(f.subject);
  if (f.object)  entities.add(f.object);
}
console.log(`facts-rebuild: ${all.length} triples, ${entities.size} distinct entities`);
'
